def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def components(value_predicate):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                if (r, c) in seen or not value_predicate(grid[r][c]):
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                while stack:
                    x, y = stack.pop()
                    comp.append((x, y))
                    for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                        if (0 <= nx < h and 0 <= ny < w and
                                (nx, ny) not in seen and
                                value_predicate(grid[nx][ny])):
                            seen.add((nx, ny))
                            stack.append((nx, ny))
                result.append(comp)
        return result

    walls = components(lambda x: x == 5)
    tiles = components(lambda x: x not in (0, 5))

    for wall in walls:
        rows = [r for r, _ in wall]
        cols = [c for _, c in wall]
        vertical = len(set(cols)) == 1
        horizontal = len(set(rows)) == 1
        if not (vertical or horizontal):
            continue

        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)

        for tile in tiles:
            tr = [r for r, _ in tile]
            tc = [c for _, c in tile]
            tminr, tmaxr = min(tr), max(tr)
            tminc, tmaxc = min(tc), max(tc)

            adjacent = False
            if vertical:
                wc = cmin
                adjacent = any(
                    (r, wc - 1) in tile or (r, wc + 1) in tile
                    for r in range(rmin, rmax + 1)
                )
                if adjacent:
                    th = tmaxr - tminr + 1
                    for r in range(rmin, rmax + 1):
                        sr = tminr + ((r - tminr) % th)
                        for c in range(tminc, tmaxc + 1):
                            if 0 <= c < w:
                                out[r][c] = grid[sr][c]
            else:
                wr = rmin
                adjacent = any(
                    (wr - 1, c) in tile or (wr + 1, c) in tile
                    for c in range(cmin, cmax + 1)
                )
                if adjacent:
                    tw = tmaxc - tminc + 1
                    for c in range(cmin, cmax + 1):
                        sc = tminc + ((c - tminc) % tw)
                        for r in range(tminr, tmaxr + 1):
                            if 0 <= r < h:
                                out[r][c] = grid[r][sc]

    return out
